def test_native_observed_plan_own_head_current_but_bound_fact_stale_blocks_package_and_round(tmp_path, _fpbca_native_case_capture) -> None:
    try:
        env = _setup(tmp_path)
        source = FactSourceBindingSchema(source_type='project_input', source_ref='project://research', source_version_ref='project-version://2')
        fact_content_v2 = env['fact'].build_content_from_authoritative_sources(normalization_contract_version='facts-v1', source_bindings=[source], facts=[CanonicalFactRecordSchema(fact_id='fact-1', fact_type='project_fact', normalized_value={'value': 2}, source_bindings=[source])])
        fact_logical = env['fact_binding'].version_ref.logical_ref
        fact_v2 = env['fact'].commit_snapshot(logical_ref=fact_logical, content=fact_content_v2, operation_ref=_op('fact-v2', 'ARTIFACT_VERSION_COMMIT'))
        env['fact'].promote_snapshot(logical_ref=fact_logical, target_version_ref=fact_v2, expected_head_revision=1, expected_active_version_id=env['fact_binding'].version_ref.artifact_version_id, operation_ref=_op('fact-v2-p', 'ARTIFACT_ACTIVE_PROMOTION'))
        with pytest.raises(EvidencePackageCurrentnessError, match='FactSnapshot source is stale'):
            env['research'].validate_evidence_package_binding_current(env['package_binding'], require_source_fresh=True)
        authorization = ResearchRoundAuthorizationBindingSchema(authorization_kind='WORKFLOW_RESEARCH', authorization_ref='workflow-start-research://fact-stale-failure')
        ref = env['research'].derive_round_ref(run_id=RUN_ID, section_id=SECTION_ID, authorization_binding=authorization, active_attempt=env['lineage'])
        record = ResearchRoundRecordSchema(round_ref=ref, round_ordinal=1, authorization_binding=authorization, source_plan_version_ref=env['plan_version'], execution_outcome=ResearchRoundExecutionOutcome.TECHNICAL_FAILURE, package_progress=ResearchPackageProgressSchema(material_package_change='UNAVAILABLE_DUE_TO_TECHNICAL_FAILURE'))
        with pytest.raises(EvidencePackageSourceBindingError, match='FactSnapshot source is stale'):
            env['research'].commit_round(round_candidate=record, operation_ref=env['research'].round_operation_ref(ref), source_plan_binding=env['plan_binding'], resulting_package_binding=None, commit_guard_context=env['lineage'], expected_progress_revision=0, expected_committed_round_count=0, expected_last_committed_round_ref=None)
    finally:
        _fpbca_native_case_capture.emit(root=tmp_path, rows=['V01', 'V04'], local_values=locals(), selector='backend/tests/test_fpbca_final65_obs_multi_agent_v3_research_runtime.py::test_native_observed_plan_own_head_current_but_bound_fact_stale_blocks_package_and_round', native_source={'path': 'D:\\MyCode\\rag-agent-shared\\backend\\tests\\test_multi_agent_v3_research_runtime.py', 'sha256': 'fd8388711961e47931603b1380c5c48a08d4d74b3f6db7657cd15d5686e6fb1a', 'function': 'test_plan_own_head_current_but_bound_fact_stale_blocks_package_and_round', 'line': 884, 'native_operation': 'EXACT_ORIGINAL_NATIVE_TEST_FLOW', 'native_refs': []}, native_local_names=[])

